claim=dict(id='C_remote_read_context',kind='obligation',concern='implementation_semantics',description='When a stable leader confirms and releases pending ReadIndex requests originating at remote eligible peers, each released request must be returned to its origin with its own original SystemCtx, so that the receiving peer exposes ReadyToRead for that request rather than another request context. This includes earlier requests released by confirmation of a later queued request.',source_ids=['src_confirm_expectation','src_forwarded_read_expectation','src_receive_expectation','src_read_api','src_read_complete','src_read_confirm','src_confirmation_emission','src_context_admission'],scope=dict(description='Correlation of confirmed remote read-index requests through the internal Peer API and its actual raft handlers, in one unchanged multi-voter configuration and term.',assumptions=['Non-Byzantine voting peers; unique nonzero contexts supplied under the caller batching contract.','A current-term log entry is committed before requests; each origin has one pending request in the examined release, allowing origin identity to correlate observations independently of context.','Ordinary messages may be lost before delivery; delivered messages are neither forged nor reordered within a sender-to-recipient stream.','The consumer obligation applies to requests actually released by confirmation, not to merely submitted or unconfirmed requests.'],excluded=['A numeric client-success deadline, absence of timeout, or proof of infinite stalling.','Application Lookup output, stale read, crash durability or a whole-cluster safety violation.','Dynamic membership, recovery, authority change, duplicate context collisions and Byzantine traffic.'],parameters={}),pending=[],grounding=dict(source_ids=['src_read_confirm','src_confirmation_emission','src_context_admission','src_read_receive','src_read_complete','src_context_generation'],expectation_ids=['src_confirm_expectation','src_forwarded_read_expectation','src_receive_expectation','src_read_api'],binding_ids=['bind_read_emission','bind_read_receive'],derivation='TestReadIndexLeaderCanBeConfirmed explicitly expects both earlier and later released readStatus objects to retain their original ctx while indices may be raised. TestReadOnlyOptionSafe expects forwarded follower requests to emerge with the originally supplied SystemCtx in readyToRead, and TestHandleFollowerReadIndexResp expects the receiver to preserve incoming context. These are implementation test expectations, not independent formal protocol authority. They compose with the public asynchronous per-RequestState outcome contract and the exact-context pendingReadIndex.addReady consumer: substituting another request context cannot identify the released original request. The obligation fixes this identity relationship and does not strengthen permitted pending or timeout outcomes into eventual success.',applicability='Stable leader with current-term committed entry, eligible origins, distinct caller contexts and a completed confirmation that releases the recorded request. Test expectation covers the exact prefix-release semantic and forwarded consumption separately; the planned controlled history must establish their composition.',unresolved=[],conflicts=[],alternatives=['Returning a higher confirmed index for an older request is permitted and intentionally excluded from the mismatch oracle.','Local-origin requests use the saved status context and provide counterevidence against generalizing the suspected issue to all read confirmations.']))
bindings=[dict(id='bind_read_emission',material_id='src_confirmation_emission',symbol='raft.handleReadIndexLeaderConfirmation',start_line=1771,end_line=1790,description='Consumes released statuses and encodes remote response context.',pending=[],associations=[dict(claim_id=claim['id'],source_ids=['src_confirmation_emission','src_confirm_expectation'],rationale='This is the boundary that must preserve the saved context for each confirmed remote request.')]),dict(id='bind_read_receive',material_id='src_read_receive',symbol='raft.handleFollowerReadIndexResp',start_line=1955,end_line=1963,description='Exposes incoming remote response context as ReadyToRead.',pending=[],associations=[dict(claim_id=claim['id'],source_ids=['src_read_receive','src_receive_expectation','src_read_complete'],rationale='The origin has no remapping here; exact context is required by the downstream pending batch lookup.')])]
x=dict(action='obligation',candidate_id=c['id'],question=q,obligation=claim,bindings=bindings,sources=sources,rationale='Ground the narrowly scoped remote read-context preservation duty in captured test expectations and the real consumer contract; construct a fixed controlled history next.',feedback=dict(ref_ids=[c['id'],'src_confirm_expectation','src_forwarded_read_expectation','src_transport_loss','src_context_generation'],answered='ReadIndex test expectations preserve each released context even when confirmation raises an earlier request index; forwarded-read tests expect original context at the requesting follower. Caller batches choose nonzero random Low and tick-derived High, and pending batch lookup requires exact context. Transport queue admission can reject messages and successful queue processing retains order. A controlled schedule can therefore lose the first context heartbeat round, admit a later context at another origin, then deliver only actual later heartbeat/reply messages in FIFO order to confirm both. Once confirm removes the prefix, heartbeat retry examines only the latest remaining pending context; no context remapping is present in follower response handling or addReady. This establishes a check design, not an observed failure or an unbounded no-progress result.',remaining=q['unknowns'],understanding='updated',rationale='A small peer-level check can directly observe the correlation duty; whole-client timeout testing would add scheduling ambiguity without answering the narrower question. The snapshot recovery surface remains independent.'))
